# Reference records from UniProt REST by query (download only; nothing uploaded)
cd /Users/jacob/Documents/Sandbox/elsa_test/ELSA/benchmarks/redesign/dpann_leads/f17_machine/refs
q() { curl -s -G "https://rest.uniprot.org/uniprotkb/search" --data-urlencode "query=$1" --data-urlencode "fields=accession,id,gene_names,organism_name,length,protein_name" --data-urlencode "format=tsv" --data-urlencode "size=5"; }
for s in "gene:Saci_0748" "gene:Saci_0568" "gene:Saci_0569" "gene:Saci_0570" "gene:Saci_0567" "gene:Pcal_0766" "gene:Pcal_0767" "gene:Pcal_0765" "gene:herA AND organism_id:273057" "gene:virB4 AND organism_id:176299" "gene:virB3 AND organism_id:176299" "gene:virB6 AND organism_id:176299" "gene:virB2 AND organism_id:176299" "gene:top6B AND organism_id:2286" "gene:top6A AND organism_id:2286" "gene:yfhM AND organism_id:83333" "gene:pbpC AND organism_id:83333" "gene:A2M AND organism_id:9606 AND reviewed:true" "gene:prgJ" "gene:prgI" "gene:prgH" "gene:trwK"; do echo "## $s"; q "$s" | tail -n +2; done
